{"command":"python3 - << 'PY'
maze=[]
with open('maze.txt') as f:
    for line in f:
        maze.append(list(line.rstrip('\n')))
rows=len(maze)
cols=len(maze[0])
from collections import deque
for r in range(rows):
    for c in range(cols):
        if maze[r][c]=='@':
            sr,sc=r,c
        if maze[r][c]=='E':
            tr,tc=r,c

def neighbors(r,c):
    for dr,dc,dir in [(-1,0,'up'),(1,0,'down'),(0,-1,'left'),(0,1,'right')]:
        nr=r+dr; nc=c+dc
        if 0<=nr<rows and 0<=nc<cols and maze[nr][nc] != '#':
            yield nr,nc,dir

prev={} # (r,c)->(pr,pc,dir)
q=deque([(sr,sc)])
visited=set([(sr,sc)])
while q:
    r,c=q.popleft()
    if (r,c)==(tr,tc):
        break
    for nr,nc,dir in neighbors(r,c):
        if (nr,nc) not in visited:
            visited.add((nr,nc))
            prev[(nr,nc)]=(r,c,dir)
            q.append((nr,nc))
# reconstruct
path=[]
cur=(tr,tc)
while cur!=(sr,sc):
    pr,pc,dir=prev[cur]
    path.append(dir)
    cur=(pr,pc)
path=list(reversed(path))
print('len', len(path))
print(' '.join(path))
PY"}

