from collections import deque, defaultdict
maze=open('maze.txt').read().splitlines()
H=len(maze); W=len(maze[0])
for y,row in enumerate(maze):
  for x,ch in enumerate(row):
    if ch=='@': sy,sx=y,x
    if ch=='E': ey,ex=y,x

dirs=[(-1,0,'up'),(1,0,'down'),(0,-1,'left'),(0,1,'right')]
prev={}
q=deque([(sy,sx)])
prev[(sy,sx)]=None
while q:
  y,x=q.popleft()
  if (y,x)==(ey,ex):
