# Mark cell categories: Start cluster 's', exit cluster 'e'
from collections import deque
start=(1,1)
end=(25,25)

def cluster(seed, passchars):
    q=deque([seed])
    seen=set([seed])
    while q:
        r,c=q.popleft()
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr=r+dr; nc=c+dc
            if 0<=nr<rows and 0<=nc<cols and maze[nr][nc] in passchars and (nr,nc) not in seen:
                seen.add((nr,nc))
                q.append((nr,nc))
    return seen
S=cluster(start,'.E')
E=cluster(end,'.@')
# Print overlay map for rows 0-26
for r in range(rows):
    line=''
    for c in range(cols):
        ch=maze[r][c]
        if (r,c) in S and (r,c) in E:
            line+='X'
        elif (r,c) in S:
            line+='s'
        elif (r,c) in E:
            line+='e'
        else:
            line+=ch
    print(line)
